from pathlib import Path
import base64

app = Path('src/controle_contas/app.py')
text = app.read_text(encoding='utf-8')

LOGO_B64 = ""

data_dir = Path('data')
data_dir.mkdir(exist_ok=True)
(data_dir / 'cc_logo_user.png').write_bytes(base64.b64decode(LOGO_B64))

start = text.find('        def render_background(w, h):\n')
end = text.find("            icons=Image.new('RGBA',(W,H),(0,0,0,0))", start)
if start < 0 or end < 0:
    raise RuntimeError('render_background final nao encontrado')
segment = text[start:end]
replacement = '''            try:\n                logo=Image.open(resource('data/cc_logo_user.png')).convert('RGBA')\n                maxw=int(W*0.28); maxh=int(H*0.34)\n                logo.thumbnail((maxw,maxh), Image.Resampling.LANCZOS)\n                lx=int(W*0.29-logo.width/2); ly=int(H*0.42-logo.height/2)\n                img.alpha_composite(logo,(lx,ly))\n            except Exception:\n                pass\n'''
changed = False
for old in ('            draw_cc_logo(img, W, H)\n','            paste_cc_logo(img, W, H)\n'):
    if old in segment:
        segment = segment.replace(old, replacement, 1)
        changed = True
if not changed:
    raise RuntimeError('logo antigo nao encontrado no render final')
text = text[:start] + segment + text[end:]

lines = text.splitlines(keepends=True)
out=[]
removed=False
for line in lines:
    if 'tk.Label(title' in line and 'Login' in line:
        removed=True
        continue
    if 'tk.Label(title' in line and "text='.'" in line:
        continue
    out.append(line)
text=''.join(out)
if not removed:
    raise RuntimeError('titulo do login nao encontrado')

login_start=text.find('    def show_login(self):')
login_end=text.find('    def login(self):', login_start)
login=text[login_start:login_end]
if 'seu Login' in login:
    raise RuntimeError('titulo ainda presente')
if "cc_logo_user.png" not in login:
    raise RuntimeError('novo logo nao carregado')
if 'draw_cc_logo(img, W, H)' in login or 'paste_cc_logo(img, W, H)' in login:
    raise RuntimeError('logo antigo ainda desenhado')

app.write_text(text, encoding='utf-8')
print('v45 final login patch applied and validated')
